package utils

import (
	"bytes"
	"log"
	"regexp"
	"strings"
)

// wagVersion is the version of wag that is generating code. Use SetWagVersion to set it.
var wagVersion = "unknown"

// disallowedVersionChars matches characters that aren't allowed in the wag version.
var disallowedVersionChars = regexp.MustCompile(`[^A-Za-z0-9 ._+-]`)

// SetWagVersion sets the version of wag noted in generated files. Characters other than letters,
// numbers, spaces, periods, dashes, pluses, and underscores are removed. If nothing is left, the version is "unknown".
func SetWagVersion(version string) {
	version = strings.TrimSpace(disallowedVersionChars.ReplaceAllString(version, ""))
	if version == "" {
		version = "unknown"
	}
	wagVersion = version
}

// OmitVersionComment disables the version comment in generated files. It's set by main at startup.
var OmitVersionComment = false

// GeneratedByText returns text noting which version of wag generated a file, or "" if
// OmitVersionComment is set.
func GeneratedByText() string {
	if OmitVersionComment {
		return ""
	}
	return "This file was generated by wag " + wagVersion + "."
}

// GeneratedByComment returns a line comment noting which version of wag generated a file, or "" if
// OmitVersionComment is set.
func GeneratedByComment() string {
	if OmitVersionComment {
		return ""
	}
	return "// " + GeneratedByText() + "\n"
}

// ExtractModuleNameAndVersionSuffix extracts module name and suffix from a package name given an outputpath.
func ExtractModuleNameAndVersionSuffix(packageName, outputPath string) (moduleName, versionSuffix string) {
	vregex, err := regexp.Compile("/v[0-9]$|/v[0-9][0-9]")
	if err != nil {
		log.Fatalf("Error checking module name: %s", err.Error())
	}
	moduleName = strings.TrimSuffix(packageName, outputPath)
	versionSuffix = vregex.FindString(moduleName)
	moduleName = strings.TrimSuffix(moduleName, versionSuffix)
	return
}

// CamelCase converts strings to CamelCase
func CamelCase(src string, capFirst bool) string {
	camelingRegex := regexp.MustCompile("[0-9A-Za-z]+")

	// commonInitialisms, taken from
	// https://github.com/golang/lint/blob/32a87160691b3c96046c0c678fe57c5bef761456/lint.go#L702
	commonInitialisms := map[string]bool{
		"API":   true,
		"ASCII": true,
		"CPU":   true,
		"CSS":   true,
		"DNS":   true,
		"EOF":   true,
		"GUID":  true,
		"HTML":  true,
		"HTTP":  true,
		"HTTPS": true,
		"ID":    true,
		"IP":    true,
		"JSON":  true,
		"LHS":   true,
		"QPS":   true,
		"RAM":   true,
		"RHS":   true,
		"RPC":   true,
		"SLA":   true,
		"SMTP":  true,
		"SQL":   true,
		"SSH":   true,
		"TCP":   true,
		"TLS":   true,
		"TTL":   true,
		"UDP":   true,
		"UI":    true,
		"UID":   true,
		"UUID":  true,
		"URI":   true,
		"URL":   true,
		"UTF8":  true,
		"VM":    true,
		"XML":   true,
		"XSRF":  true,
		"XSS":   true,
	}

	byteSrc := []byte(src)
	chunks := camelingRegex.FindAll(byteSrc, -1)
	for idx, val := range chunks {
		if idx == 0 && !capFirst {
			chunks[idx] = val
		} else if commonInitialisms[string(bytes.ToUpper(val)[:])] {
			chunks[idx] = bytes.ToUpper(val)
		} else {
			chunks[idx] = bytes.Title(val)
		}
	}
	return string(bytes.Join(chunks, nil))
}
